import { useCallback, useEffect, useRef, useState } from 'react';
import { InstructionType } from '../type';

export type Callback = (updated: string[]) => void;

const useInputInstructionList = (allInstructions: InstructionType[]) => {
  const [inputCommands, setInputCommands] = useState<string[]>([]);
  const [curCommand, setCurCommand] = useState<InstructionType | undefined>(
    undefined,
  );
  const callbackRef = useRef<Callback | null>(null);

  // 设置一级指令
  const setPrimaryCommand = useCallback(
    (primary: string, callback?: Callback) => {
      callbackRef.current = callback || null;
      setInputCommands([primary]);
    },
    [],
  );

  // 设置二级指令
  const setSecondaryCommand = useCallback(
    (secondary: string, callback?: Callback) => {
      callbackRef.current = callback || null;
      setInputCommands([secondary]);
    },
    [],
  );

  // 删除指令1级或2级
  const removeCommand = useCallback(
    (commandNum: 1 | 2, callback?: Callback) => {
      callbackRef.current = callback || null;
      setInputCommands([]);
    },
    [],
  );

  // 合并设置指令
  const setCommand = useCallback(
    (command: string, callback?: Callback) => {
      if (!command) {
        return setInputCommands([]);
      }
      if (command.startsWith('@')) {
        // 如果是一级指令
        setPrimaryCommand(command, callback);
      } else {
        // 否则，视为二级指令
        setSecondaryCommand(command, callback);
      }
    },
    [setPrimaryCommand, setSecondaryCommand, allInstructions],
  );

  // 更新 curCommand
  useEffect(() => {
    if (inputCommands.length === 0) {
      setCurCommand(undefined);
    } else if (inputCommands.length === 1) {
      const primaryCommand = allInstructions.find(
        (instr) => instr.englishName === inputCommands[0],
      );
      setCurCommand(primaryCommand || undefined);
    } else if (inputCommands.length === 2) {
      const secondaryCommand = allInstructions
        .flatMap((instr) => instr.children || [])
        .find((child) => child.englishName === inputCommands[1]);
      setCurCommand(secondaryCommand || undefined);
    }
  }, [inputCommands, allInstructions]);

  useEffect(() => {
    if (callbackRef.current) {
      callbackRef.current(inputCommands);
      callbackRef.current = null;
    }
  }, [inputCommands]);

  return {
    curCommand,
    inputCommands,
    setCommand,
    removeCommand,
  };
};

export default useInputInstructionList;
