import useRegisterMessage from '@/services/JsBridge/useRegisterMessage';
import { useChatStore } from '@/store';
import { useCallback } from 'react';

export interface SelectCode {
  code: string;
  source: string;
  endLine: number;
  endOffset: number;
  startLine: number;
  startOffset: number;
}

export const useCodeSelection = () => {
  const { setSelectedCode } = useChatStore();

  const onSelectCode = useCallback((payload: SelectCode) => {
    const { code, endLine, endOffset, startLine, startOffset, source } =
      payload;
    let selectCode = code;
    if (code.length > 70000) {
      console.log('选中代码长度超出限制 70000 字符，截断选中代码', code.length);
      selectCode = code.slice(0, 70000);
    }
    setSelectedCode({
      code: selectCode,
      endLine,
      endOffset,
      startLine,
      startOffset,
      source,
    });
  }, []);

  useRegisterMessage('selectCodeContext', onSelectCode);
};
