import FilesSelector, { FilesSelectorRef } from '@/components/FilesSelector';
import ImgBtn from '@/components/ImgBtn';
import ModeSwitch from '@/components/ModeSwitch';
import SelectedCodeList from '@/pages/Agentic/SelectedCodeList';
import { useChatStore, useGlobalStore } from '@/store';
import { AutoComplete, Input } from 'antd';
import { TextAreaRef } from 'antd/es/input/TextArea';
import classNames from 'classnames';
import { forwardRef, useEffect, useMemo, useRef, useState } from 'react';
import Abort from '../Abort';
import ModelBtn from '../ModelBtn';
import ProviderPopover from '../ModelConfigPopOver';
import PreviewImg from '../PreviewImg';
import SendBtn from '../SendBtn';
import { defaultPlaceholder, instructionList } from './common';
import { useInputInstructionList, useSimulateTriggering } from './hooks';
import styles from './index.module.less';
import PrefixInput from './PrefixInput';
import SelectedCode from './SelectedCode';
import CommandBtns from './ToolBar/Command';
import FileBtn from './ToolBar/FileBtn';
import {
  ActionType,
  Option,
  ScopeInfoItem,
  sendProps,
  SendQuestionPayload,
} from './type';
import { findInstructionByName } from './utils/findInstructionByName';

export interface NewUserInputRef {
  setCommandAndInputValue: (command: string[], value: string) => void;
}

interface NewUserInputProps {
  isCommandShow?: boolean;
  isFileShow?: boolean;
  isModelShow?: boolean;
  isImgShow?: boolean;
  loading: boolean;
  isActive?: boolean;
  onAbort: () => void;
  sendQuestion?: (payload: Partial<SendQuestionPayload>) => void;
  placeHolder?: string;
  chatId: string;
  tabRef?: React.MutableRefObject<any>;
}

const NewUserInput = forwardRef<NewUserInputRef, NewUserInputProps>(
  ({
    isCommandShow = true,
    isFileShow = true,
    isModelShow = true,
    isImgShow = true,
    loading,
    sendQuestion,
    onAbort,
    isActive = true,
    placeHolder,
    chatId,
    tabRef,
  }) => {
    const {
      pluginConfig: { theme = 'dark' },
    } = useGlobalStore();
    const { selectedCode } = useChatStore();
    const { inputCommands, setCommand, curCommand, removeCommand } =
      useInputInstructionList(instructionList);

    const [filterOption, setFilterOption] = useState<Array<Option>>([]);
    const [open, setOpen] = useState<boolean>(false);
    const [inputValue, setInputValue] = useState<string>('');
    const [isShow, setIsShow] = useState<boolean>(false);
    const [scopeInfo, setScopeInfo] = useState<Array<ScopeInfoItem>>([]);
    const [isComposing, setIsComposing] = useState<boolean>(false);
    const [imgArr, setImgArr] = useState<Array<string>>([]);
    const [uploading, setUploading] = useState<boolean>(false);
    const [popoverOpen, setPopoverOpen] = useState(false);

    const inputRef = useRef<TextAreaRef>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const fileRef = useRef<FilesSelectorRef>(null);

    // 监听指令
    useSimulateTriggering({
      sendQuestion,
      loading,
      isActive,
      instructionList,
    });

    // 自动聚焦
    useEffect(() => {
      if (!isActive) return;
      setTimeout(() => inputRef.current?.focus(), 100);
    }, [isActive]);

    // 有数据时就打开弹窗
    useEffect(() => {
      setOpen(filterOption?.length > 0);
    }, [filterOption]);

    const sendChat = async (data: sendProps) => {
      if (loading) return;
      const { commands, commandInfo = {}, question } = data;
      sendQuestion?.({
        command: commands,
        commandInfo: commandInfo || null,
        question,
        context: selectedCode.code,
        scopeInfo: {
          type: 'file',
          data: JSON.stringify(scopeInfo),
        },
        img: imgArr,
      });
      setInputValue('');
      // 清空图片
      setImgArr([]);
    };

    const onSendQuestion = (e?: React.MouseEvent) => {
      if (e?.preventDefault) {
        e?.preventDefault();
        e?.stopPropagation();
      }

      if (!inputValue && !inputCommands?.length) return;
      sendChat({
        commands: inputCommands,
        commandInfo: curCommand,
        question: inputValue || '',
      });
    };

    // 选择选项时触发
    const onSelectCommand = async (value: string) => {
      if (value.includes('file')) {
        fileRef.current?.setSeleteFile(value);
      }
      const targetInstruction = findInstructionByName(instructionList, value);
      if (!targetInstruction) return;
      setInputValue('');
      setFilterOption([]);
      switch (targetInstruction?.actionType) {
        case ActionType.SEND: {
          setCommand(value, (commands) => {
            sendChat({
              commands,
              commandInfo: targetInstruction,
              question: '',
            });
          });
          break;
        }
        case ActionType.WAIT: {
          setCommand(targetInstruction.englishName);
          break;
        }
      }
      return false;
    };

    useEffect(() => {
      const handleKeyDown = (event: any) => {
        if (event.key === 'Backspace' && !inputValue && inputCommands.length) {
          removeCommand(inputCommands[1] ? 2 : 1);
        }
      };
      const dom = inputRef.current?.resizableTextArea?.textArea;
      dom?.addEventListener('keydown', handleKeyDown);
      return () => dom?.removeEventListener('keydown', handleKeyDown);
    }, [inputCommands, inputValue]);

    const onEnter = (event: React.KeyboardEvent<HTMLTextAreaElement>) => {
      if (isComposing) return;
      if (event.key === 'Enter' && event.shiftKey) return;
      if (event.key === 'Enter' && !open && !event.metaKey && !event.ctrlKey) {
        event.preventDefault();
        event.stopPropagation();
        onSendQuestion();
      }
    };

    const targetPlaceHolder = useMemo(() => {
      if (inputCommands.length) {
        return findInstructionByName(
          instructionList,
          inputCommands[1] ? inputCommands[1] : inputCommands[0],
        )?.placeholder;
      } else {
        return defaultPlaceholder;
      }
    }, [inputCommands]);

    return (
      <div className={styles.newUserInput} ref={containerRef}>
        {loading && <Abort onAbort={onAbort} chatId={chatId} />}
        {isCommandShow && <SelectedCode />}
        {imgArr?.length > 0 && (
          <PreviewImg imgArr={imgArr} setImgArr={setImgArr} />
        )}
        <SelectedCodeList />
        <FilesSelector
          ref={fileRef}
          isShow={isShow}
          setIsShow={setIsShow}
          scopeInfo={scopeInfo}
          setScopeInfo={setScopeInfo}
        />
        <div className={styles.footer}>
          <div className={styles.outer}>
            <div
              className={classNames(
                styles.inputContainer,
                theme === 'dark'
                  ? styles.inputContainerDark
                  : styles.inputContainerLight,
              )}
            >
              <PrefixInput
                inputCommands={inputCommands}
                instructionList={instructionList}
                removeCommand={removeCommand}
              />
              <AutoComplete
                open={open}
                options={filterOption}
                onSelect={onSelectCommand}
                value={inputValue || ''}
                onDropdownVisibleChange={(open) => {
                  if (!open) setOpen(open);
                }}
                className={styles.autoComplete}
                popupClassName={styles.autoCompleteDropdown}
                defaultActiveFirstOption
              >
                <Input.TextArea
                  ref={inputRef}
                  value={inputValue}
                  onChange={(e) => setInputValue(e.target.value)}
                  onPressEnter={(e) => onEnter(e)}
                  className={styles.input}
                  autoSize={{ minRows: 1, maxRows: 6 }}
                  placeholder={placeHolder || targetPlaceHolder}
                  onCompositionStart={() => setIsComposing(true)}
                  onCompositionEnd={() => setIsComposing(false)}
                />
              </AutoComplete>
            </div>
            <div
              className={classNames(
                styles.toolBar,
                theme === 'dark' ? styles.toolBarDark : styles.toolBarLight,
              )}
            >
              <div className={styles.left}>
                {isCommandShow && (
                  <CommandBtns
                    inputValue={inputValue}
                    inputCommands={inputCommands}
                    setFilterOption={setFilterOption}
                  />
                )}
                {isFileShow && (
                  <FileBtn
                    open={open}
                    setOpen={setOpen}
                    setFilterOption={setFilterOption}
                  />
                )}
                {isImgShow && (
                  <ImgBtn
                    setImgArr={setImgArr}
                    setUploading={setUploading}
                    imgArr={imgArr}
                    chatId={chatId}
                    tabRef={tabRef}
                  />
                )}
              </div>
              <div className={styles.right}>
                <ModeSwitch />
                {isModelShow && (
                  <ProviderPopover
                    open={popoverOpen}
                    onClose={() => setPopoverOpen(false)}
                    anchor={
                      <div onClick={() => setPopoverOpen(!popoverOpen)}>
                        <ModelBtn />
                      </div>
                    }
                  />
                )}
                <div className={styles.sendBtnWrapper}>
                  <SendBtn
                    loading={loading}
                    inputValue={inputValue}
                    onSendQuestion={onSendQuestion}
                    uploading={uploading}
                  />
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  },
);
export default NewUserInput;
