import { InstructionType } from '@/components/NewUserInput/type';
import { Tooltip } from 'antd';
import styles from '../index.module.less';
import { Option } from '../type';

export const parseInstructionToOption = (
  instructionList: Array<InstructionType>,
  prevOption: Array<Option> = [],
): Array<Option> => {
  instructionList.forEach((instruction) => {
    const { children, label, name, englishName, category = '' } = instruction;
    if (children?.length > 0) {
      parseInstructionToOption(children, prevOption);
    }
    prevOption.push({
      label: (
        <Tooltip className={styles.autoCompleteItem} title={label}>
          <div className={styles.autoCompleteItem_first}>
            {englishName.startsWith('/') ? (
              <span>
                {name} ({englishName.slice(1)})
              </span>
            ) : (
              <span>{name}</span>
            )}
          </div>
          <div className={styles.autoCompleteItem_second}>
            {englishName.startsWith('/') ? (
              <span>{category}</span>
            ) : (
              <span>{label}</span>
            )}
          </div>
        </Tooltip>
      ),
      value: englishName,
      filterValue: Array.from(new Set([name, englishName])),
      category,
    });
  });

  let atList: Option[] = [];
  let otherList: Option[] = [];

  prevOption.forEach((item) => {
    if (item.value.startsWith('@')) {
      atList.push(item);
    } else {
      otherList.push(item);
    }
  });
  return [...atList, ...otherList];
};
