import { ReactComponent as CancelSVG } from '@/assets/footer/cancel.svg';
import jsBridgePostMessage from '@/services/JsBridge/jsBridgePostMessage';
import { useChatStore } from '@/store';
import { Tooltip } from 'antd';
import { FC, memo, useCallback } from 'react';
import Highlight from 'react-highlight';
import styles from './index.module.less';

const SelectedCode: FC = () => {
  const { selectedCode } = useChatStore();
  const onDeselectCode = useCallback(() => {
    jsBridgePostMessage({
      command: 'deselectCodeContext',
    });
  }, []);

  return selectedCode.code ? (
    <div className={styles.selectedCodeContainer}>
      <Tooltip title="取消选中" placement="left">
        <CancelSVG className={styles.deselectIcon} onClick={onDeselectCode} />
      </Tooltip>
      <Highlight className={styles.selectedCode}>{selectedCode.code}</Highlight>
    </div>
  ) : null;
};
export default memo(SelectedCode);
