export interface ProcessedImage {
  type: 'base64';
  media_type: string;
  data: string;
}

export const processBase64Images = (imgArr: string[]): ProcessedImage[] => {
  return imgArr.map((base64) => {
    const match = base64.match(/^data:(image\/\w+);base64,/);
    const mediaType = match ? match[1] : 'image/jpeg';
    return {
      type: 'base64',
      media_type: mediaType,
      data: base64.split(',')[1],
    };
  });
};
