import logo from '@/assets/codelink/logo.png';
import Loading from '@/components/Loading';
import MarkdownRender from '@/components/MarkdownRender';
import { MessageDetailItem } from '@/services/Api/agentic';
import classNames from 'classnames';
import { FC, HTMLAttributes } from 'react';
import UserInfo from './UserInfo';
import styles from './index.module.less';

const responseName = 'CodeLink';

export interface ReferenceInfo {
  icon: string;
  name: string;
  startLine: number;
  endLine: number;
  path: string;
  messageId: string;
}

interface ResponseCardProps extends HTMLAttributes<HTMLDivElement> {
  chatId: string;
  message: MessageDetailItem;
  updateMessage: (msg: MessageDetailItem) => void;
  isGeneratingResponse: boolean;
}

const ResponseCard: FC<ResponseCardProps> = (props) => {
  const { message, className, isGeneratingResponse, ...restProps } = props;
  const { response } = message;
  const command = message.displayQuestion?.split('\n\n')[0];

  return (
    <div
      {...restProps}
      className={classNames(className, styles.card, styles.responseCard)}
    >
      <UserInfo name={responseName} avatar={logo} />
      {response && (
        <MarkdownRender
          allowRawHtml
          message={response}
          payload={message.props}
          messageId={message.messageId}
          command={command}
        />
      )}
      {/* 生成答案中，给个loading的效果 */}
      {isGeneratingResponse && <Loading isShowHead={false} text="正在回答中" />}
    </div>
  );
};
export default ResponseCard;
