import { ReactComponent as FileSVG } from '@/assets/common/file.svg';
import { jsBridgePostMessageWithCallback } from '@/services/JsBridge/jsBridgePostMessage';
import { CloseOutlined } from '@ant-design/icons';
import { Button, Tooltip, message } from 'antd';
import { forwardRef, useEffect, useImperativeHandle, useRef } from 'react';
import styles from './index.module.less';
import SearchFile from './SearchFile';
export interface ScopeInfoItem {
  content: string;
  name: string;
  path: string;
  changeType?: string;
  extContent?: string;
  type?: string;
  startLine?: number;
  endLine?: number;
  startOffset?: number;
  endOffset?: number;
  language?: string;
}

interface FilesSelectorProps {
  setScopeInfo: (data: ScopeInfoItem[]) => void;
  scopeInfo: ScopeInfoItem[];
  setIsShow: (data: boolean) => void;
  isShow: boolean;
}

export interface FilesSelectorRef {
  setSeleteFile: (type: string) => void; // 这里定义暴露给父组件的方法或属性
}

const FilesSelector = forwardRef<FilesSelectorRef, FilesSelectorProps>(
  ({ scopeInfo, setScopeInfo, isShow, setIsShow }, ref) => {
    const filesSelector = useRef<HTMLDivElement | null>(null);

    useEffect(() => {
      // 如果文件数量超过 20 个，截取前 20 个并弹出提示
      if (scopeInfo.length > 20) {
        message.warning('最多选择 20 个文件！');
      }
      const finalFiles = scopeInfo.slice(0, 20);

      // 仅当过滤后的结果不同才更新状态
      if (JSON.stringify(finalFiles) !== JSON.stringify(scopeInfo)) {
        setScopeInfo(finalFiles);
      }
    }, [scopeInfo]);

    // 点击随机地方关闭文件选择器
    useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
        if (
          filesSelector.current &&
          !filesSelector.current.contains(event.target as Node)
        ) {
          setIsShow(false);
        }
      };

      document.addEventListener('mousedown', handleClickOutside);

      return () => {
        document.removeEventListener('mousedown', handleClickOutside);
      };
    }, []);

    // 取消选择文件
    const handleCancel = (item: ScopeInfoItem) => {
      const newData = scopeInfo.filter((i) => i.path !== item.path);
      setScopeInfo(newData);
    };

    // 从插件端拉取相应的文件
    const getFileData = async () => {
      const res = await jsBridgePostMessageWithCallback(
        {
          command: 'getFileContent',
        },
        5000,
      );
      if (res.data) {
        const {
          content,
          type,
          name,
          path,
          startLine,
          endLine,
          language,
          startOffset,
          endOffset,
        } = res.data;
        setScopeInfo([
          {
            content,
            type,
            name,
            path,
            startLine,
            endLine,
            language,
            startOffset,
            endOffset,
          },
        ]);
      }
    };

    // 暴露的方法，触发快捷选中某些文件
    const setSeleteFile = (type: string) => {
      if (!type) return;
      switch (type) {
        case 'file_1':
          setIsShow(true);
          break;
        case 'file_2':
          getFileData();
          break;
      }
    };

    // 使用 useImperativeHandle 暴露方法
    useImperativeHandle(ref, () => ({
      setSeleteFile,
    }));

    return (
      <div className={styles.FilesSelector} ref={filesSelector}>
        {isShow && (
          <SearchFile scopeInfo={scopeInfo} setScopeInfo={setScopeInfo} />
        )}
        <div className={styles.bottom}>
          {scopeInfo?.length > 0 && (
            <div className={styles.fileContainer}>
              {scopeInfo?.map((item) => {
                return (
                  <div
                    key={`${item.name}-${item.path}-tag`}
                    className={styles.fileTag}
                  >
                    <div className={styles.iconWrapper}>
                      <FileSVG style={{ width: 14, height: 14 }} />
                    </div>
                    <Tooltip placement="top" title={item.path}>
                      <span className={styles.name}>{item.name}</span>
                    </Tooltip>
                    <CloseOutlined
                      className={styles.cancel}
                      onClick={() => handleCancel(item)}
                    />
                  </div>
                );
              })}
              <Button
                className={styles.FilesSelector_clear}
                type="link"
                size="small"
                onClick={() => {
                  setScopeInfo([]);
                }}
              >
                清空
              </Button>
            </div>
          )}
        </div>
      </div>
    );
  },
);

export default FilesSelector;
