import { jsBridgePostMessageWithCallback } from '@/services/JsBridge/jsBridgePostMessage';
import useRegisterMessage from '@/services/JsBridge/useRegisterMessage';
import { useGlobalStore } from '@/store';
import { getFileIcon } from '@/utils/fileIcon';
import { Empty, Input, Spin, Tooltip } from 'antd';
import { debounce } from 'lodash';
import { useCallback, useEffect, useRef, useState } from 'react';
import { Virtuoso } from 'react-virtuoso';
import { v4 as uuid } from 'uuid';
import { ScopeInfoItem } from '..';
import styles from './index.module.less';

interface SearchFileProps {
  setScopeInfo: (data: ScopeInfoItem[]) => void;
  scopeInfo: ScopeInfoItem[];
}

const SearchFile: React.FC<SearchFileProps> = ({ scopeInfo, setScopeInfo }) => {
  const {
    pluginConfig: { theme },
  } = useGlobalStore();
  // 文件列表总数据
  const [fileData, setData] = useState<Array<ScopeInfoItem>>([]);
  const [searchValue, setSearchValue] = useState<string>('');
  const searchId = useRef<string>(uuid());
  const [loading, setLoading] = useState<boolean>();

  // 请求默认文件列表
  const fetchDefaultData = async () => {
    const res = await jsBridgePostMessageWithCallback({
      command: 'getDefaultFileList',
    });
    if (res?.data) {
      setData(res.data);
    }
  };

  useEffect(() => {
    fetchDefaultData();
  }, []);

  const fetchSearchData = async (userInput: string) => {
    // 给插件发送指令之前更新 uuid
    searchId.current = uuid();
    setLoading(true);
    const res = await jsBridgePostMessageWithCallback({
      command: 'searchFileList',
      data: {
        uuid: searchId.current,
        userInput,
      },
    });
    // TODO:此逻辑只在Vscode插件中使用，jetbrains插件技术问题无法同步返回，改用searchFileListResp监听
    if (res?.data) {
      setLoading(false);
      setData(res.data);
    } else {
      setLoading(false);
      setData([]);
    }
  };

  const debouncedFetchSearchData = useCallback(
    debounce(fetchSearchData, 500),
    [],
  );

  // 此逻辑只有jetbrains插件中使用，vscode插件直接返回结果
  const onReceiveSearchData = useCallback(
    (data: { uuid: string; fileContentDTOList: Array<ScopeInfoItem> }) => {
      if (data.uuid !== searchId.current) return;
      setLoading(false);
      setData(data.fileContentDTOList);
    },
    [searchId.current],
  );

  useRegisterMessage('searchFileListResp', onReceiveSearchData);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchValue(e.target.value);
    debouncedFetchSearchData(e.target.value);
  };

  // 选择文件
  const handleClick = (item: ScopeInfoItem) => {
    let isDelete = false;
    let list = scopeInfo?.filter((i) => {
      if (i.path === item.path) {
        isDelete = true;
        return false;
      }
      return true;
    });
    if (!isDelete) {
      list = [
        ...scopeInfo,
        {
          path: item.path,
          name: item.name,
          content: item.content,
          type: item.type,
          startLine: item.startLine,
          endLine: item.endLine,
          language: item.language,
          startOffset: item.startOffset,
          endOffset: item.endOffset,
        },
      ];
    }
    setScopeInfo(list);
  };

  const getActive = (item: ScopeInfoItem) => {
    return scopeInfo?.map((i) => i.path).includes(item.path);
  };

  const renderItem = useCallback(
    (item: ScopeInfoItem) => {
      return (
        <div
          key={item.path}
          onClick={() => handleClick(item)}
          className={`${styles.listItem} ${
            getActive(item) ? styles.active : ''
          }`}
        >
          <div className={styles.listItem_filename}>
            <img
              style={{ width: 14, height: 14 }}
              src={getFileIcon(item.path)}
            />
            <span>{item.name}</span>
          </div>
          <Tooltip title={item.path}>
            <span>{item.path}</span>
          </Tooltip>
        </div>
      );
    },
    [scopeInfo, handleClick],
  );

  return (
    <div
      className={`${styles.SearchFile} ${
        theme === 'dark' ? styles.darkTheme : styles.lightTheme
      }`}
    >
      <div
        className={`${styles.inputContainer} ${
          theme === 'dark' ? styles.darkTheme : styles.lightTheme
        }`}
      >
        <Input
          placeholder="至少输入 3 个字符，最多返回 500 条"
          size="small"
          onChange={handleChange}
          value={searchValue}
        />
      </div>
      <div
        style={{ height: 180, margin: 10 }}
        className={loading || !fileData?.length ? styles.loadingBox : ''}
      >
        {loading ? (
          <Spin />
        ) : fileData?.length > 0 ? (
          <Virtuoso
            style={{ height: '100%' }}
            data={fileData}
            itemContent={(index, item) => renderItem(item)}
          />
        ) : (
          <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} />
        )}
      </div>
    </div>
  );
};

export default SearchFile;
