import { MessageDetailItem, MessageItem } from '@/services/Api/agentic';
import { useCallback } from 'react';

export const useMessageHandlers = (
  setMessageList: (fn: (prev: MessageItem[]) => MessageItem[]) => void,
) => {
  const onCreateMessage = useCallback((value: MessageDetailItem) => {
    setMessageList((prev = []) => [...prev, value]);
  }, []);

  const onReceiveMessage = useCallback(
    (payload: { content: string; messageId: string }) => {
      const { content, messageId } = payload;
      setMessageList((prev) => {
        if (!prev) return prev;
        const targetMessage = prev?.find(
          (item) => item.messageId === messageId,
        );
        if (targetMessage && 'response' in targetMessage) {
          targetMessage.response = `${targetMessage?.response ?? ''}${content}`;
        }
        return [...prev];
      });
    },
    [],
  );

  const onFinish = useCallback(() => {
    setMessageList((prev) => {
      if (!prev) return prev;
      return [...prev];
    });
  }, []);

  const onError = useCallback(
    (payload: { error: string | Error; messageId: string }) => {
      const { error, messageId } = payload;
      setMessageList((prev) => {
        if (!prev) return prev;
        const targetMessage = prev?.find(
          (item) => item.messageId === messageId,
        );
        if (targetMessage && 'response' in targetMessage) {
          targetMessage.response = error?.toString() ?? '';
        }
        return [...prev];
      });
    },
    [],
  );

  return {
    onCreateMessage,
    onReceiveMessage,
    onFinish,
    onError,
  };
};
