import logo from '@/assets/codelink/logo.png';
import UserInfo from '@/components/UserInfo';
import classNames from 'classnames';
import styles from './index.module.less';

interface LoadingComponentProps {
  isShowHead?: boolean;
  text?: string;
  userText?: string;
  userLogo?: string;
  size?: number;
}

const Loading: React.FC<LoadingComponentProps> = ({
  isShowHead = true,
  text = '正在执行中',
  userText = 'CodeLink',
  userLogo = logo,
  size = 28,
}) => {
  return (
    <div
      className={classNames(
        styles.loadingContainer,
        !isShowHead ? styles.loadingNoHead : '',
      )}
    >
      {isShowHead ? (
        <UserInfo name={userText} avatar={userLogo} size={size} />
      ) : (
        ''
      )}
      <div className={styles.loadingContainer_main}>
        <span className={styles.loadingContainer_text}>{text}</span>
      </div>
    </div>
  );
};
export default Loading;
