const startNewlineReg = /^(\n*)/;
const endNewlineReg = /(\n*)$/;

export default function formatQuestion(payload: {
  command?: Array<string> | string;
  question?: string;
  context?: string;
}): string {
  const { command = '', question = '', context } = payload;
  let parsedCommand: string = '';
  if (typeof command === 'string') {
    parsedCommand = command
      .replace(startNewlineReg, '')
      .replace(endNewlineReg, '');
  } else if (Array.isArray(command)) {
    parsedCommand = command
      ?.map((item) =>
        item?.replace(startNewlineReg, '').replace(endNewlineReg, ''),
      )
      .join('');
  }
  let parsedContext = context;
  if (parsedContext) {
    parsedContext = parsedContext
      .replace(startNewlineReg, '\n')
      .replace(endNewlineReg, '\n');
    parsedContext = '```' + parsedContext + '```';
  }
  const parsedQuestion = question
    .replace(startNewlineReg, '')
    .replace(endNewlineReg, '');
  return [parsedCommand, parsedQuestion, parsedContext || '']
    .filter(Boolean)
    .join('\n\n');
}
