import { ReactComponent as FileSVG } from '@/assets/common/file.svg';
import { ReactComponent as ImgSVG } from '@/assets/footer/img.svg';
import { ReactComponent as DefaultUserSVG } from '@/assets/user/icon-user.svg';
import MarkdownRender from '@/components/MarkdownRender';
import { MessageDetailItem } from '@/services/Api/agentic';
import jsBridgePostMessage from '@/services/JsBridge/jsBridgePostMessage';
import getImgExtensionFromBase64 from '@/utils/getImgExtensionFromBase64';
import getRandomFileName from '@/utils/getRandomFileName';
import { message, Popover } from 'antd';
import classNames from 'classnames';
import { FC, HTMLAttributes, useMemo } from 'react';
import { v4 as uuid } from 'uuid';
import UserInfo from './UserInfo';
import styles from './index.module.less';

// 图片加载失败时显示的默认图片
const DEFAULT_IMAGE =
  'https://file.ljcdn.com/nebula/img-load-err_1741420542629.svg';

interface RequestCardProps extends HTMLAttributes<HTMLDivElement> {
  messageDetail: MessageDetailItem;
}

interface FileItem {
  path: string;
  name: string;
}

const RequestCard: FC<RequestCardProps> = (props) => {
  const { messageDetail, className, ...restProps } = props;
  const command = messageDetail.displayQuestion?.split('\n\n')[0];

  const fileData = useMemo(() => {
    let list: FileItem[] = [];
    try {
      list = JSON.parse(messageDetail.scopeInfo?.data || '[]');
    } catch (err) {}
    console.log('当前对话文件：', list);
    return list;
  }, [messageDetail.scopeInfo]);

  const clickFile = (file: FileItem) => {
    jsBridgePostMessage({
      command: 'fileLinkage',
      data: {
        uri: file.path,
        messageId: messageDetail.messageId,
      },
    });
  };

  const handleClick = (item: string) => {
    let extension = getImgExtensionFromBase64(item);
    if (!extension) {
      const parsedUrl = new URL(item);
      const filePath = parsedUrl.pathname;
      const beforeExclamation = filePath?.split('!')?.[0];
      extension = beforeExclamation?.split('.')?.pop() || '';
    }

    if (!extension) return message.error('获取文件后缀失败');
    jsBridgePostMessage({
      command: 'picPreview',
      data: {
        title: getRandomFileName(extension),
        content: '',
        url: item,
      },
    });
  };

  const renderImages = useMemo(() => {
    return (messageDetail.img?.length ?? 0) > 0
      ? messageDetail.img?.map((item: string, index: number) => (
          <Popover
            key={uuid()}
            content={
              <div className={styles.previewContent}>
                <img
                  src={item}
                  alt={`图片 ${index + 1}`}
                  onError={(e) => (e.currentTarget.src = DEFAULT_IMAGE)}
                />
              </div>
            }
            title={`图片 ${index + 1}`}
            trigger="hover"
            placement="top"
            overlayClassName={styles.previewPopover}
          >
            <div className={styles.extag} onClick={() => handleClick(item)}>
              <div className={styles.iconWrapper}>
                <ImgSVG />
              </div>
              <span>图片 {index + 1}</span>
            </div>
          </Popover>
        ))
      : null;
  }, [messageDetail.img]);

  return (
    <div
      {...restProps}
      className={classNames(className, styles.card, styles.requestCard)}
    >
      <UserInfo avatar={<DefaultUserSVG />} />
      <div>
        {fileData?.length > 0 && (
          <div className={styles.requestCard_file}>
            {fileData.map((file: FileItem) => (
              <div
                key={file.path}
                className={styles.extag}
                onClick={() => {
                  clickFile(file);
                }}
              >
                <div className={styles.iconWrapper}>
                  <FileSVG style={{ width: 14, height: 14 }} />
                </div>
                <span>{file.name}</span>
              </div>
            ))}
          </div>
        )}
        {renderImages && (
          <div className={styles.requestCard_file} style={{ gap: 10 }}>
            {renderImages}
          </div>
        )}
        <MarkdownRender
          message={messageDetail.displayQuestion}
          payload={messageDetail.props}
          messageId={messageDetail.messageId}
          command={command}
        />
      </div>
    </div>
  );
};

export default RequestCard;
