import { history, useLocation } from '@umijs/max';
import { useEffect, useRef } from 'react';

export const useRouteStateHandler = () => {
  const location = useLocation();
  const hasProcessedRef = useRef<boolean>(false);

  useEffect(() => {
    // 确保组件已经初始化完成，并且有 location.state
    if (location?.state && !hasProcessedRef.current) {
      const state = location.state as { command?: string; data?: any };
      const { command } = state;
      if (command === 'onInlineChat') {
        hasProcessedRef.current = true;

        // 清除 location.state，避免重复处理
        history.replace(
          {
            pathname: location.pathname,
          },
          null,
        );
      }
    }
  }, [location.state]);

  // 当 location.state 变化时，重置处理状态
  useEffect(() => {
    hasProcessedRef.current = false;
  }, [location.state]);
};
