import { getModelName } from '@/pages/Agentic/modelConfig';
import { MessageDetailItem, MessageItem } from '@/services/Api/agentic';
import jsBridgePostMessage from '@/services/JsBridge/jsBridgePostMessage';
import { useAgenticStore, useGlobalStore } from '@/store';
import sendChat, {
  NewQuestion,
  ResendQuestion,
} from '@/utils/sendChat/sendChat';
import { message } from 'antd';
import { noop } from 'lodash';
import { useCallback, useMemo, useRef, useState } from 'react';

export const useSendMessage = (
  chatId: string,
  messageList: MessageItem[],
  setMessageList: (fn: (prev: MessageItem[]) => MessageItem[]) => void,
  handlers: {
    onCreateMessage: (value: MessageDetailItem) => void;
    onReceiveMessage: (payload: { content: string; messageId: string }) => void;
    onFinish: () => void;
    onError: (payload: { error: string | Error; messageId: string }) => void;
  },
  setQuestionLoading: (loading: boolean) => void,
  scrollToBottom: (smooth?: boolean) => void,
) => {
  const {
    projectConfig: { sideCarIDEInfo },
    pluginConfig: { provider },
  } = useGlobalStore();
  const { agentModel } = useAgenticStore();

  // 获取模型名称
  const modelName = useMemo(() => getModelName(agentModel), [agentModel]);

  const abortRef = useRef<() => void>(noop);
  const [payloadCache, setPayloadCache] = useState<
    NewQuestion & { messageId?: string; again?: boolean }
  >();

  const onDeselectCode = () => {
    jsBridgePostMessage({
      command: 'deselectCodeContext',
    });
  };

  const onSendQuestion = useCallback(
    (payload?: Partial<NewQuestion>, props?: Record<string, any>) => {
      let parsedPayload: NewQuestion | ResendQuestion = {};
      if (!payload) {
        const resendMessageId =
          messageList?.[messageList.length - 1]?.messageId;
        if (!resendMessageId) {
          message.error('没有可以重发的消息');
          return;
        }

        setMessageList((prev) => {
          if (!prev) return prev;
          const targetMessage = prev[prev!.length - 1];
          if (targetMessage) {
            (targetMessage as MessageDetailItem).response = '';
          }
          return [...prev!];
        });
        parsedPayload = {
          ...payloadCache,
          messageId: resendMessageId,
        } as ResendQuestion;
      } else {
        const { workspaceFileType } = window.projectConfig;
        parsedPayload = {
          ...payload,
          workspaceFileType,
        } as NewQuestion;
      }

      onDeselectCode();

      // 使用传入的滚动函数，延迟执行确保DOM更新完成
      setTimeout(() => {
        scrollToBottom(true);
      }, 300);

      sendChat({
        chatId,
        payload: parsedPayload as NewQuestion,
        onCreateMessage: handlers.onCreateMessage,
        onReceiveMessage: handlers.onReceiveMessage,
        onFinish: handlers.onFinish,
        onError: handlers.onError,
        abortRef,
        props,
        onLoadingStatusChange: setQuestionLoading,
        info: {
          sideCarIDEInfo,
          provider,
          modelName,
        },
      });
    },
    [messageList, chatId, handlers, payloadCache, scrollToBottom],
  );

  const onAbort = useCallback(() => {
    abortRef.current();
    setQuestionLoading(false);
  }, [abortRef.current]);

  return {
    onSendQuestion,
    onAbort,
    abortRef,
  };
};
