import { Option } from '../type';
export const getAllFirstCommand = (options: Option[]) => {
  return options.filter((item) => item.value.startsWith('@'));
};

export const getAllSecondCommand = (options: Option[]) => {
  return options.filter((item) => item.value.startsWith('/'));
};

export const getSpecificCommand = (options: Option[], command: string) => {
  return options.filter((item) => item.category === command);
};
