import { InstructionType } from '../type';

export const findInstructionByName = (
  dataList: InstructionType[],
  name?: string,
): InstructionType | null => {
  if (!name) return null;
  for (const instruction of dataList) {
    if (instruction.englishName === name) {
      return instruction;
    }
    if (instruction?.children?.length > 0) {
      const childMatch = findInstructionByName(instruction.children, name);
      if (childMatch) {
        return childMatch;
      }
    }
  }
  return null;
};
