import { ChatStreamMessage } from '@/interface/global';
import { getExchangeId, MessageDetailItem } from '@/services/Api/agentic';
import { FetchSSE } from '@/services/Api/requestInstance';
import { ProviderType, SideCarIDEInfoType } from '@/store/Global/types';
import formatQuestion from '@/utils/formatQuestion';
import generateStringHash from '@/utils/generateStringHash';
import { message } from 'antd';
import { MutableRefObject } from 'react';
import buildChatPayload from './buildChatPayload';

export interface NewQuestion {
  command?: string;
  question?: string;
  context?: string;
  scopeInfo?: {
    type: string;
    data: string;
  };
  commandInfo?: any;
  pluginPrompt?: Record<string, any>;
  img?: Array<string>;
}

export interface ResendQuestion {
  messageId: string;
}

export interface SendChatParams {
  chatId: string;
  /**
   * 问题内容，如果没有则认为是重问上一个问题
   */
  payload: NewQuestion;
  info: {
    sideCarIDEInfo: SideCarIDEInfoType;
    provider: ProviderType;
    modelName: string;
  };
  onCreateMessage?: (value: MessageDetailItem) => void;
  onReceiveMessage?: (payload: { content: string; messageId: string }) => void;
  onFinish?: (payload: { finishReason: string; messageId: string }) => void;
  onError?: (payload: { error: string | Error; messageId: string }) => void;
  abortRef?: MutableRefObject<() => void>;
  onLoadingStatusChange?: (loading: boolean) => void;
  props?: Record<string, any>;
}

export default async function sendChat(params: SendChatParams) {
  const {
    chatId,
    payload,
    onCreateMessage,
    onReceiveMessage,
    onFinish,
    onError,
    abortRef,
    props = {},
    onLoadingStatusChange,
    info,
  } = params;

  const { sideCarIDEInfo, provider, modelName } = info;

  if (!provider) {
    message.info('请先配置 API KEY 再使用哦～');
    return;
  }

  const { selected_provider, selected_provider_api_key } = provider;
  const obj = selected_provider_api_key?.[selected_provider];
  if (!obj || Object.keys(obj)?.length === 0) {
    message.info('请先配置 API KEY 再使用哦～');
    return;
  }

  const { command, question, context, scopeInfo, img } = payload;

  const { sideCarPort } = sideCarIDEInfo;

  const messageId = generateStringHash(`${chatId}${new Date().getTime()}`);
  const displayQuestion = formatQuestion({ command, question, context });
  const newMessage: MessageDetailItem = {
    messageId,
    displayQuestion,
    request: displayQuestion,
    props,
    response: '',
    scopeInfo,
    img,
  };
  onCreateMessage?.(newMessage);

  const res = await getExchangeId(
    { sessionId: chatId },
    `http://localhost:${sideCarPort}`,
  );

  if (!res.success) {
    onError?.({
      error: '获取 exchangeId 失败',
      messageId,
    });
  }

  const data = {
    chatId,
    messageId,
    command,
    question,
    context,
    scopeInfo,
    img,
    displayQuestion,
  };

  const exchange_id = res.data.exchange_id.split('_')[1];

  const finalData = buildChatPayload(
    data,
    chatId,
    exchange_id,
    sideCarIDEInfo,
    provider,
    modelName,
  );

  const onMessage = (message: ChatStreamMessage) => {
    if (message?.choices) {
      message?.choices.forEach((item) => {
        if (item?.delta?.content) {
          onReceiveMessage?.({ content: item?.delta?.content, messageId });
        }
        if (item?.finishReason) {
          onFinish?.({ finishReason: item?.finishReason, messageId });
        }
      });
    }
  };

  const fetchInstance = new FetchSSE({
    type: 'chat',
    url: '/api/agentic/agent_session_chat',
    sideCarPort,
    onMessage,
    onError: (e) => onError?.({ error: e, messageId }),
    onFinish: (finishReason: string) => onFinish?.({ finishReason, messageId }),
    data: finalData,
    onLoadingStatusChange,
  });
  if (abortRef) {
    abortRef.current = fetchInstance.abort.bind(fetchInstance);
  }

  return {
    abort: fetchInstance.abort.bind(fetchInstance),
  };
}
