import { ReactComponent as CommandSVG } from '@/assets/footer/command2.svg';
import { Tooltip } from 'antd';
import { useEffect, useMemo } from 'react';
import { instructionList } from '../../common';
import { Option } from '../../type';
import { getAllSecondCommand } from '../../utils/getCommand';
import { parseInstructionToOption } from '../../utils/parseInstructionToOption';
import realTimeMatching from '../../utils/realTimeMatching';
import styles from '../index.module.less';

interface CommandBtnsProps {
  inputValue: string;
  inputCommands: string[];
  setFilterOption: React.Dispatch<React.SetStateAction<Option[]>>;
}

const CommandBtns: React.FC<CommandBtnsProps> = ({
  inputValue,
  inputCommands,
  setFilterOption,
}) => {
  const totalOption = useMemo(
    () => parseInstructionToOption(instructionList),
    [instructionList],
  );

  // 通过用户输入内容实时匹配指令
  useEffect(() => {
    if (!inputValue || !inputValue.startsWith('/')) {
      setFilterOption([]);
      return;
    }
    setFilterOption(realTimeMatching(inputValue, totalOption));
  }, [inputValue, inputCommands, totalOption]);

  const handleSecondCommandClick = () => {
    const curFilterOption =
      !inputValue || !inputValue.startsWith('/')
        ? getAllSecondCommand(totalOption)
        : realTimeMatching(inputValue, totalOption);
    setFilterOption(curFilterOption);
  };

  return (
    <>
      <Tooltip title="/ 指令">
        <div className={styles.toolbar_btn} onClick={handleSecondCommandClick}>
          <CommandSVG />
        </div>
      </Tooltip>
    </>
  );
};
export default CommandBtns;
