import { FC, useEffect, useRef } from 'react';
import ChatTab from './ChatTab';
import { useChatList } from './hooks/useChatList';
import { useCodeSelection } from './hooks/useCodeSelection';
import { useRouteStateHandler } from './hooks/useRouteStateHandler';
import styles from './index.module.less';

const Chat: FC = () => {
  const { chatList, onCreateNewChat } = useChatList();
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  useCodeSelection();
  useRouteStateHandler();

  // 获取当前聊天会话
  const currentChat = chatList[0];

  // 为了解决 IDEA 消息注入失败的问题，在这里对初始化创建会话进行轮询判断
  useEffect(() => {
    if (chatList.length === 0) {
      if (window.JavaPanelBridge) {
        onCreateNewChat();
      } else {
        const checkJavaPanel = () => {
          if (window.JavaPanelBridge) {
            onCreateNewChat();
            if (timerRef.current) {
              clearTimeout(timerRef.current);
              timerRef.current = null;
            }
          } else {
            timerRef.current = setTimeout(checkJavaPanel, 100);
          }
        };
        checkJavaPanel();
      }
    }

    return () => {
      if (timerRef.current) {
        clearTimeout(timerRef.current);
        timerRef.current = null;
      }
    };
  }, [chatList, onCreateNewChat]);

  return (
    <div className={styles.chat}>
      {currentChat && (
        <ChatTab
          openTime={currentChat.openTime}
          isActive={true}
          chatId={currentChat.chatId}
          chatType={currentChat.chatType}
        />
      )}
    </div>
  );
};

export default Chat;
