import { Option } from '../type';
const realTimeMatching = (inputValue: string, optionArr: Option[]) => {
  if (
    !inputValue ||
    (!inputValue.startsWith('@') && !inputValue.startsWith('/'))
  ) {
    return [];
  }
  const res = [];
  for (let item of optionArr) {
    if (item.filterValue && Array.isArray(item.filterValue)) {
      for (let fv of item.filterValue) {
        if (inputValue.length > 1) {
          if (
            fv[0] === inputValue[0] &&
            // 去除指令再匹配
            fv.slice(1).includes(inputValue.slice(1))
          ) {
            res.push(item);
            break;
          }
        } else {
          // 此时 inputValue 只可能是 @ 或者 /
          if (fv.includes(inputValue)) {
            res.push(item);
            break;
          }
        }
      }
    }
  }
  return res;
};
export default realTimeMatching;
