import { modelConfig } from '@/pages/Agentic/modelConfig';
import { ProviderType, SideCarIDEInfoType } from '@/store/Global/types';
import { processBase64Images } from '../imageUtils';
import { UserContext } from '../sendAgentChat/type';
import { NewQuestion } from './sendChat';

interface FileItem {
  name: string;
  start_position?: {
    line: number;
    character: number;
    byteOffset: number;
  };
  end_position?: {
    line: number;
    character: number;
    byteOffset: number;
  };
  content: string;
  fs_file_path: string;
  type: string;
  language: string;
}

export default (
  payload: Partial<NewQuestion>,
  chatId: string,
  exchangeId: string,
  sideCarIDEInfo: SideCarIDEInfoType,
  provider: ProviderType,
  modelName: string,
) => {
  const {
    editorUrl,
    rootDirectory,
    projectLabels,
    projectId,
    openFiles,
    shell,
    aideRules: aiteRules,
  } = sideCarIDEInfo;

  const { question, scopeInfo, img, context, command } = payload;

  // Parse scopeInfo.data JSON string and transform to FileItem format
  let files: FileItem[] = [];
  if (scopeInfo?.data) {
    try {
      const parsedData = JSON.parse(scopeInfo.data);
      if (Array.isArray(parsedData)) {
        files = parsedData.map((item: any) => ({
          name: item.name || '',
          content: item.content || '',
          fs_file_path: item.path || '',
          type: item.type,
          language: item.language,
          start_position: {
            line: item.startLine,
            character: item.startOffset,
            byteOffset: item.startOffset,
          },
          end_position: {
            line: item.endLine,
            character: item.endOffset,
            byteOffset: item.endOffset,
          },
        }));
      }
    } catch (error) {
      console.error('Failed to parse scopeInfo.data:', error);
    }
  }

  const images = img ? processBase64Images(img) : [];

  const userContext: UserContext = {
    variables: files,
    file_content_map: [],
    images: images || [],
    folder_paths: [],
    prev_chat_histories: [],
    is_plan_generation: false,
    is_plan_execution_until: null,
    is_plan_append: false,
    with_lsp_enrichment: false,
    is_plan_drop_from: null,
    selected_code: context || undefined,
    command: (command?.length ?? 0) > 0 ? command?.[0] : undefined,
  };

  return {
    session_id: chatId,
    exchange_id: `request_${exchangeId}`,
    editor_url: editorUrl || '',
    query: question || '',
    root_directory: rootDirectory || '',
    project_labels: projectLabels || [],
    project_id: projectId || '',
    all_files: [],
    open_files: openFiles.filter(Boolean),
    shell: shell || '',
    // 这个是同一个吗？？
    aide_rules: aiteRules || '',
    reasoning: false,
    is_devtools_context: false,
    model_configuration: {
      ...modelConfig,
      slow_model: modelName,
      model_name: provider.model_name,
      selected_provider: provider.selected_provider,
      selected_provider_api_key: provider.selected_provider_api_key,
    },
    codebase_search: false,
    access_token: '',
    repo_ref: `local/${rootDirectory || '/'}`,
    agent_mode: '4',
    user_context: userContext,
    semantic_search: false,
    can_use_deploy: false,
    can_use_fix_bug: false,
    command_auto_run: false,
  };
};
