import { getChatHistoryMessageList, MessageItem } from '@/services/Api/agentic';
import { useChatStore, useGlobalStore } from '@/store';
import { useCallback, useEffect, useState } from 'react';

export const useMessageList = (chatId: string, chatType: 'new' | 'history') => {
  const { chatMessageList, setChatMessageList } = useChatStore();
  const {
    projectConfig: {
      sideCarIDEInfo: { sideCarPort },
    },
  } = useGlobalStore();
  const [messageList, setMessageList] = useState<MessageItem[]>([]);
  const [loading, setLoading] = useState(chatType === 'history');

  // 当chatId或chatType改变时，重置本地状态
  useEffect(() => {
    setMessageList([]);
    setLoading(chatType === 'history');
  }, [chatId, chatType]);

  // TODO:更优雅一点
  useEffect(() => {
    if (!chatId || !chatMessageList[chatId]?.length) return;
    if (messageList !== chatMessageList[chatId]) {
      setMessageList(chatMessageList[chatId]);
    }
  }, [chatMessageList, chatId]);

  useEffect(() => {
    if (!messageList?.length) return;
    if (chatMessageList[chatId] !== messageList) {
      setChatMessageList(chatId, messageList);
    }
  }, [messageList, chatId]);

  const fetchHistoryData = useCallback(async () => {
    if (!messageList?.length && chatType === 'history') {
      setLoading(true);
      const { success, data } = await getChatHistoryMessageList(
        { chatId },
        `http://localhost:${sideCarPort}`,
      );
      if (success) {
        setMessageList(data);
      }
    }
    setLoading(false);
  }, [messageList, chatId, chatType]);

  useEffect(() => {
    fetchHistoryData();
  }, [fetchHistoryData]);

  return {
    messageList,
    setMessageList,
    loading,
    setLoading,
  };
};
