import { MessageDetailItem, MessageItem } from '@/services/Api/agentic';
import { FC, useEffect, useRef, useState } from 'react';
import RequestCard from './RequestCard';
import ResponseCard from './ResponseCard';
import styles from './index.module.less';

interface ConversionProps {
  chatId: string;
  message: MessageItem;
  // 长会话的时候，懒加载消息内容后的回调
  updateMessage: (msg: MessageDetailItem) => void;
  // 是否是当前激活的问答(最后一条问答)
  isActive: boolean;
  loading: boolean;
}

const Conversion: FC<ConversionProps> = (props) => {
  const { chatId, message, updateMessage, isActive, loading } = props;
  const isGeneratingResponse = isActive && loading;
  const domRef = useRef<HTMLDivElement>(null);

  const [showResponse, setShowResponse] = useState(true);
  useEffect(() => {
    const parentDom = domRef.current?.parentNode as HTMLElement;
    const scrollListener = () => {
      const { bottom, top } = domRef.current!.getBoundingClientRect();
      // 如果在可视区域的两倍以上，则清除内容，避免渲染大量无用数据
      if (top > window.innerHeight * 2 || bottom < -window.innerHeight * 2) {
        setShowResponse(false);
      } else {
        setShowResponse(true);
      }
    };
    if (parentDom && 'response' in message && domRef.current) {
      parentDom.addEventListener('scroll', scrollListener);
    }
    return () => {
      setShowResponse(true);
      parentDom?.removeEventListener('scroll', scrollListener);
    };
  }, [message, domRef.current]);

  return (
    <div ref={domRef} className={styles.conversion}>
      <>
        {'displayQuestion' in message && message.displayQuestion && (
          <RequestCard messageDetail={message} />
        )}
        {'response' in message && showResponse && (
          <ResponseCard
            chatId={chatId}
            message={message}
            updateMessage={updateMessage}
            isGeneratingResponse={isGeneratingResponse}
          />
        )}
      </>
    </div>
  );
};
export default Conversion;
