import { CloseCircleOutlined } from '@ant-design/icons';
import { useCallback } from 'react';
import { Callback } from '../hooks/useInputInstructionList';
import { findInstructionByName } from '../utils/findInstructionByName';
import styles from './index.module.less';

interface PrefixInputProps {
  inputCommands: string[];
  removeCommand: (commandNum: 1 | 2, callback?: Callback) => void;
  instructionList: any[];
}

const PrefixInput: React.FC<PrefixInputProps> = ({
  inputCommands,
  instructionList,
  removeCommand,
}) => {
  const getCommonData = useCallback(
    (value: string) => findInstructionByName(instructionList, value),
    [instructionList],
  );

  const onDeleteCommand = useCallback((command: string) => {
    if (command.startsWith('@')) {
      removeCommand(1);
    } else if (command.startsWith('/')) {
      removeCommand(2);
    }
  }, []);

  return (
    <div className={styles.prefixInput}>
      {inputCommands.map((item) => (
        <div key={item} className={styles.commandContainer}>
          <span className={styles.command}>{getCommonData(item)?.name}</span>
          <CloseCircleOutlined
            onClick={() => onDeleteCommand(item)}
            className={styles.deleteCommand}
          />
        </div>
      ))}
    </div>
  );
};
export default PrefixInput;
