// 模拟指令触发hooks，通常是插件触发
import { history, useLocation } from '@umijs/max';
import { useEffect } from 'react';
import { InstructionType, SendQuestionPayload } from '../type';
import { findInstructionByName } from '../utils/findInstructionByName';
export interface FooterProps {
  sendQuestion?: (props: Partial<SendQuestionPayload>) => void;
  loading: boolean;
  isActive?: boolean;
  chatId?: string;
  instructionList?: InstructionType[];
}

const useSimulateTriggering = (props: FooterProps) => {
  const { sendQuestion, loading, isActive = false, instructionList } = props;
  const location = useLocation();

  const clearState = () => {
    // 执行过后清除 location.state
    history.replace(
      {
        pathname: location.pathname,
      },
      null,
    );
  };

  //   插件模拟触发chat指令
  const onInlineChat = (data: any) => {
    if (loading) return;
    let { command, question, context, commandId } = data;
    let info = null;
    if (instructionList) {
      info = findInstructionByName(instructionList, command);
    }
    if (info?.category) {
      command = [info?.category, command];
    } else {
      command = [command];
    }
    sendQuestion?.({
      command: command,
      commandId,
      question,
      commandInfo: info,
      context,
      scopeInfo: {
        type: 'file',
        data: '',
      },
    });
    clearState();
  };

  useEffect(() => {
    // 当前已打开对话框才执行当前操作
    if (isActive && location?.state) {
      const state = location.state as { command?: string; data?: any };
      if (!state?.command) return;
      const { command, data } = state;
      if (command === 'onInlineChat') {
        // 添加一个小延迟，确保组件完全初始化
        setTimeout(() => {
          onInlineChat(data);
        }, 100);
      }
    }
  }, [location.state, isActive]);
};

export default useSimulateTriggering;
