import jsBridgePostMessage from '@/services/JsBridge/jsBridgePostMessage';
import copyToClipboard from '@/utils/copyToClipboard';
import { Button, Tooltip } from 'antd';
import { debounce } from 'lodash';
import React from 'react';
import { v4 as uuid } from 'uuid';
import styles from './index.module.less';

interface CommandRenderProps {
  command: string;
}

const CommandRender: React.FC<CommandRenderProps> = ({ command }) => {
  const handleClick = debounce((command: string) => {
    jsBridgePostMessage({
      command: 'executeCommand',
      data: {
        commandId: uuid(),
        command: command.replace(/\n/g, ' '),
        inTerminal: true,
      },
    });
  }, 200);

  const handleCopy = debounce((command: string) => {
    copyToClipboard(command, '复制成功');
  }, 200);

  return (
    <div className={styles.commandCard}>
      <pre className={styles.pre}>{command}</pre>
      <div className={styles.btnGroup}>
        <Tooltip title="复制">
          <Button
            size="small"
            className={styles.button}
            onClick={() => handleCopy(command)}
          >
            copy
          </Button>
        </Tooltip>
        <Tooltip title="执行">
          <Button
            size="small"
            className={styles.button}
            onClick={() => handleClick(command)}
          >
            run
          </Button>
        </Tooltip>
      </div>
    </div>
  );
};

export default CommandRender;
