import { ReactNode } from 'react';

export interface ScopeInfoItem {
  content: string;
  name: string;
  path: string;
  icon?: string;
}

export interface sendProps {
  commands: string[];
  commandInfo: any;
  question: string;
  scopeInfo?: any;
}

export interface SendQuestionPayload {
  commandId: number | undefined;
  command: Array<string>;
  question: string | undefined;
  context: string | undefined;
  commandInfo?: any;
  img?: Array<string>;
  scopeInfo?:
    | {
        type: string;
        data: string;
      }
    | string;
}

export type SendQuestionType = (
  type: 'chat' | 'agent',
  payload: SendQuestionPayload,
) => void;

export enum ActionType {
  // 直接发出去
  SEND = 'send',
  // 跳转路由
  JUMP = 'jump',
  // 留在输入框等待操作
  WAIT = 'wait',
}

export interface InstructionType {
  id: number;
  category?: string;
  icon: 'info' | 'pipeline' | 'code' | 'devops' | 'search';
  label?: string;
  name: string;
  englishName: string;
  placeholder?: string;
  actionType: ActionType;
  children: Array<InstructionType>;
  url?: string;
  allowRegenerate?: boolean;
  isAgent?: boolean;
  isExtraOption?: boolean;
}

export interface Option {
  label: ReactNode;
  value: string;
  filterValue: string[];
  category?: string;
}
