import { ReactComponent as FileUploadSVG } from '@/assets/footer/file_upload.svg';
import { Tooltip } from 'antd';
import { fileOption } from '../../common';
import styles from '../index.module.less';

interface FileBtnProps {
  open: boolean;
  setOpen: (open: boolean) => void;
  setFilterOption: React.Dispatch<React.SetStateAction<any[]>>;
}

const FileBtn: React.FC<FileBtnProps> = ({ setOpen, setFilterOption }) => {
  const handleFileClick = () => {
    setFilterOption(fileOption);
    setOpen(true);
  };

  return (
    <Tooltip title="选择文件">
      <div className={`${styles.toolbar_btn}`} onClick={handleFileClick}>
        <FileUploadSVG />
      </div>
    </Tooltip>
  );
};
export default FileBtn;
