import NewUserInput, { NewUserInputRef } from '@/components/NewUserInput';
import { SendQuestionPayload } from '@/components/NewUserInput/type';
import InitPage from '@/pages/InitPage';
import { MessageDetailItem } from '@/services/Api/agentic';
import { NewQuestion } from '@/utils/sendChat/sendChat';
import { Spin } from 'antd';
import { FC, useCallback, useEffect, useRef, useState } from 'react';
import Conversion from './Conversion';
import { useAutoScroll } from './hooks/useAutoScroll';
import { useMessageHandlers } from './hooks/useMessageHandlers';
import { useMessageList } from './hooks/useMessageList';
import { useSendMessage } from './hooks/useSendMessage';
import styles from './index.module.less';

interface ChatTabProps {
  chatId: string;
  // 新建的对话还是从历史记录里选的对话，如果是历史对话，需要加载历史消息
  chatType: 'new' | 'history';
  isActive: boolean;
  openTime: number;
}

export interface AsyncMessage {
  status: 'sent' | 'received' | 'failed';
  chatId: string;
  message: string;
}

const ChatTab: FC<ChatTabProps> = (props) => {
  const { chatId, chatType, isActive } = props;
  const singleTab = useRef(null);
  const userInputRef = useRef<NewUserInputRef>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const { messageList, setMessageList, loading } = useMessageList(
    chatId,
    chatType,
  );
  const [questionLoading, setQuestionLoading] = useState<boolean>(false);

  // 自动滚动功能
  const { scrollContainerRef, scrollToBottom } = useAutoScroll();

  const handlers = useMessageHandlers(setMessageList);
  const { onSendQuestion, onAbort } = useSendMessage(
    chatId,
    messageList,
    setMessageList,
    handlers,
    setQuestionLoading,
    scrollToBottom, // 传递滚动函数
  );

  // 创建适配器函数，将 SendQuestionPayload 转换为 NewQuestion
  const handleSendQuestion = useCallback(
    (payload: Partial<SendQuestionPayload>) => {
      const newQuestion: Partial<NewQuestion> = {
        command: payload.command?.[0], // 取第一个命令
        question: payload.question,
        context: payload.context,
        scopeInfo:
          typeof payload.scopeInfo === 'string'
            ? { type: 'string', data: payload.scopeInfo }
            : payload.scopeInfo,
        commandInfo: payload.commandInfo,
        img: payload.img,
      };
      onSendQuestion(newQuestion);
    },
    [onSendQuestion],
  );

  // 当chatId改变时，重置loading状态
  useEffect(() => {
    setQuestionLoading(false);
  }, [chatId]);

  // 当消息列表更新时，自动滚动到底部
  useEffect(() => {
    if (messageList && messageList.length > 0) {
      setTimeout(() => {
        scrollToBottom(true);
      }, 100);
    }
  }, [messageList, scrollToBottom]);

  const updateMessage = (msg: MessageDetailItem) => {
    const { messageId } = msg;
    const targetMessageIndex = (messageList || []).findIndex(
      (item) => item.messageId === messageId,
    );
    if (targetMessageIndex !== -1) {
      setMessageList((prev) => {
        if (!prev) return prev;
        prev[targetMessageIndex] = { ...msg, response: msg.response || '' };
        return [...prev];
      });
    }
  };

  return (
    <div className={styles.chatTab} ref={singleTab}>
      <div ref={containerRef} className={styles.chatList}>
        <div ref={scrollContainerRef} className={styles.scrollToBottom}>
          {(messageList?.length ?? 0) > 0 ? (
            messageList?.map((item, index) => (
              <Conversion
                key={item.messageId}
                message={item}
                chatId={chatId}
                loading={questionLoading}
                isActive={index === messageList.length - 1}
                updateMessage={updateMessage}
              />
            ))
          ) : loading ? (
            <Spin className={styles.loading} />
          ) : (
            <InitPage />
          )}
        </div>
      </div>
      <NewUserInput
        loading={questionLoading}
        sendQuestion={handleSendQuestion}
        onAbort={onAbort}
        isActive={isActive}
        chatId={chatId}
        ref={userInputRef}
        tabRef={singleTab}
      />
    </div>
  );
};

export default ChatTab;
