// 获取文件图标的方法
export function getFileIcon(filePath: string) {
  // 解析文件扩展名
  const extMatch = filePath.match(/\.([^.]+)$/);
  const ext = extMatch ? extMatch[1] : '';

  // 根据扩展名从映射中获取图标
  const icon = fileIconMap[ext] || fileIconMap['default'];

  return icon;
}
