import { FC, memo, useCallback, useRef } from 'react';
import ReactMarkdown from 'react-markdown';
import rehypeRaw from 'rehype-raw';
import CodeRender from '../CodeRender';
import CommandRender from './CommandRender';
import LinkRender from './LinkRender';
import styles from './index.module.less';
import { commandArr } from './regular';
import type { MarkdownRenderProps } from './type';

const MarkdownRender: FC<MarkdownRenderProps> = ({
  message,
  allowRawHtml = false,
  messageId,
  componentCode,
}) => {
  const markdownRenderRef = useRef<HTMLDivElement>(null);

  // 自定义code模块的解析 useCallback 包裹防止重复渲染
  const codeAnalysis = useCallback((props: any) => {
    const { node, className = '' } = props;
    const content = node.children[0]?.value;

    const [language] = className.replace(/^language-/, '').split(':');

    if (commandArr.includes(language.toLowerCase())) {
      return <CommandRender command={content} />;
    }
    return <CodeRender {...props} />;
  }, []);

  const LinkAnalysis = useCallback((props: any) => {
    return (
      <LinkRender
        {...props}
        messageId={messageId}
        componentCode={componentCode}
      />
    );
  }, []);

  return (
    message && (
      <div ref={markdownRenderRef}>
        <ReactMarkdown
          components={{
            code: codeAnalysis,
            a: LinkAnalysis,
          }}
          // @ts-ignore
          rehypePlugins={allowRawHtml ? [rehypeRaw] : []}
          className={styles.messageCard}
        >
          {message}
        </ReactMarkdown>
      </div>
    )
  );
};

export default memo(MarkdownRender);
